 string BuilderDesktopFile { get { return Path.Combine(Root,"desktop-widgets.json"); } }

 void StartBuilderDesktop(){
  if(builderDesktopState!=null)return;
  try{builderDesktopState=File.Exists(BuilderDesktopFile)?new JavaScriptSerializer().Deserialize<WidgetBuilderDesktopState>(File.ReadAllText(BuilderDesktopFile)):null;}catch{builderDesktopState=null;}
  if(builderDesktopState==null)builderDesktopState=new WidgetBuilderDesktopState();
  foreach(var item in builderDesktopState.widgets.Where(x=>x.enabled&&x.project!=null).ToArray())ShowBuilderDesktop(item);
  builderDesktopTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};
  builderDesktopTimer.Tick+=delegate{RefreshBuilderDesktop();};builderDesktopTimer.Start();
 }
 void SaveBuilderDesktop(){Directory.CreateDirectory(Path.GetDirectoryName(BuilderDesktopFile));File.WriteAllText(BuilderDesktopFile,Pretty(new JavaScriptSerializer().Serialize(builderDesktopState)));}
 void LoadBuilderDesktopState(){try{builderDesktopState=File.Exists(BuilderDesktopFile)?new JavaScriptSerializer().Deserialize<WidgetBuilderDesktopState>(File.ReadAllText(BuilderDesktopFile)):null;}catch{builderDesktopState=null;}if(builderDesktopState==null)builderDesktopState=new WidgetBuilderDesktopState();}
 void ReloadBuilderDesktop(){if(builderDesktopTimer!=null){builderDesktopTimer.Stop();builderDesktopTimer=null;}foreach(var window in builderDesktopWindows.Values.ToArray())window.Close();builderDesktopWindows.Clear();builderDesktopExecutions.Clear();builderDesktopState=null;StartBuilderDesktop();}
