 void DeployBuilderWidget(){
  var errors=ValidateBuilder();if(errors.Count>0){MessageBox.Show(builderWindow,String.Join("\n",errors),"Fix before adding");return;}
  if(builderDesktopState==null){if(standaloneWidgetBuilder)LoadBuilderDesktopState();else StartBuilderDesktop();}var copy=CloneBuilderProject(builderProject);double width=DesktopBuilderNumber(copy,copy.ui_tree,"width",360),height=DesktopBuilderNumber(copy,copy.ui_tree,"height",180);
  var deployment=new WidgetBuilderDeployment{name=copy.name,project=copy,x=SystemParameters.WorkArea.Left+(SystemParameters.WorkArea.Width-width)/2,y=SystemParameters.WorkArea.Top+(SystemParameters.WorkArea.Height-height)/2};
  builderDesktopState.widgets.Add(deployment);SaveBuilderDesktop();if(standaloneWidgetBuilder)SignalBuilderDesktopReload();else ShowBuilderDesktop(deployment);
 }
 void ShowBuilderDesktop(WidgetBuilderDeployment deployment){
  if(deployment==null||deployment.project==null||deployment.project.ui_tree==null)return;Window existing;if(builderDesktopWindows.TryGetValue(deployment.id,out existing)){DrawBuilderDesktop(deployment);existing.Show();return;}
  var window=new Window{Title="Awl Widget · "+deployment.name,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,AllowsTransparency=true,Background=Brushes.Transparent,ShowInTaskbar=false,ShowActivated=false,Topmost=false};builderDesktopWindows[deployment.id]=window;
  window.SourceInitialized+=delegate{var h=new WindowInteropHelper(window).Handle;Native.SetWindowLong(h,-20,Native.GetWindowLong(h,-20)|0x80|0x08000000);};
  EnableDesktopWidgetDrag(window,()=>deployment.locked,(x,y)=>{deployment.x=x;deployment.y=y;deployment.relative_x=WidgetPositionRatio(x,true,window.Width);deployment.relative_y=WidgetPositionRatio(y,false,window.Height);SaveBuilderDesktop();});
  var menu=new ContextMenu();ThemeContextMenu(menu);var edit=new MenuItem{Header="Edit in Widget Builder"};edit.Click+=delegate{OpenWidgetBuilder();builderProject=CloneBuilderProject(deployment.project);builderSelected=builderProject.ui_tree;builderHistory.Clear();builderHistoryIndex=-1;SnapshotBuilder(false);builderTab="UI";DrawBuilder();};menu.Items.Add(edit);
  var locked=new MenuItem{Header="Lock movement",IsCheckable=true,IsChecked=deployment.locked};locked.Click+=delegate{deployment.locked=locked.IsChecked;SaveBuilderDesktop();};menu.Items.Add(locked);
  var hide=new MenuItem{Header="Hide when covered",IsCheckable=true,IsChecked=deployment.hide_when_covered};hide.Click+=delegate{deployment.hide_when_covered=hide.IsChecked;SaveBuilderDesktop();};menu.Items.Add(hide);menu.Items.Add(new Separator());
  var remove=new MenuItem{Header="Remove from desktop"};remove.Click+=delegate{RemoveBuilderDeployment(deployment.id);};menu.Items.Add(remove);window.ContextMenu=menu;
